  const langCodes={it:'IT',en:'EN',fr:'FR',es:'ES',de:'DE'};
  const saved=localStorage.getItem('site-language');
  const browser=(navigator.language||'it').slice(0,2);
  let current=translations[saved]?saved:(translations[browser]?browser:'it');
  function apply(lang){current=translations[lang]?lang:'it';document.documentElement.lang=current;document.querySelectorAll('[data-i18n]').forEach(el=>{const value=translations[current][el.dataset.i18n];if(value!==undefined)el.innerHTML=value;});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const value=translations[current][el.dataset.i18nPlaceholder];if(value!==undefined)el.placeholder=value;});document.querySelectorAll('[data-i18n-aria]').forEach(el=>{const value=translations[current][el.dataset.i18nAria];if(value!==undefined)el.setAttribute('aria-label',value);});document.querySelectorAll('body *').forEach(el=>{if(el.children.length===0){const raw=el.textContent.trim();const translated=autoText[raw]?.[current];if(translated)el.textContent=translated;}});const titleMap={'it':'Moussa Salisou — Docente e sviluppatore','en':'Moussa Salisou — Teacher and Developer','fr':'Moussa Salisou — Enseignant et développeur','es':'Moussa Salisou — Docente y desarrollador','de':'Moussa Salisou — Dozent und Entwickler'};if(document.title.includes('Moussa Salisou')&&!document.title.includes('LearnCode'))document.title=titleMap[current]||document.title;document.querySelectorAll('.language-current').forEach(el=>el.textContent=langCodes[current]);localStorage.setItem('site-language',current);}
  window.MOUSSA_I18N_LOADED = true;
  window.MOUSSA_APPLY_LANGUAGE = apply;
  const init=()=>{
    apply(current);
  };
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',init,{once:true});
  }else{
    init();
  }
